# Read an Academic Passage: about 200 words of expository text, five questions.
# Q(d, domain, stem, key, [3 wrong], explanation); domain "detail" (facts and
# negative facts), "vocab" (word in context) or "reason" (inference, the
# relationship between ideas, the purpose of all or part of the text).

def Q(d, dom, stem, key, wrongs, expl):
    assert dom in ("detail", "vocab", "reason") and len(wrongs) == 3, stem
    return dict(d=d, dom=dom, stem=stem, key=key, wrongs=wrongs, expl=expl)


ACAD = [
  dict(id="TOEFLR-T1-AP1", test=1, module=1, variant=None, title="Surviving in the Desert",
       text="Desert plants face a simple problem: rain is rare, but the sun is strong almost every day. Many of them solve it by storing water. A cactus, for example, has a thick stem that swells after a storm and slowly shrinks during the long dry months that follow. Its leaves have been reduced to spines, which lose far less water than broad leaves and also discourage thirsty animals from taking a bite.\n\nTiming matters as well. Most plants open the tiny pores on their surface during the day to take in carbon dioxide, but every open pore also lets water escape. Many cacti reverse this pattern. They open their pores at night, when the air is cooler and more humid, store the carbon dioxide in a chemical form, and use it for photosynthesis the next day with their pores tightly closed.\n\nOther desert plants avoid the dry season altogether. Their seeds can lie in the soil for years. When a heavy rain finally arrives, they sprout, flower and produce new seeds within a few weeks, long before the ground dries out again.",
       qs=[
         Q(1, "detail", "According to the passage, what happens to a cactus stem after a storm?", "It swells with stored water", ["It loses its spines", "It closes its pores for good", "It produces new seeds"], "The passage says the thick stem \"swells after a storm\" and then shrinks as the stored water is used."),
         Q(2, "vocab", "The word \"discourage\" in the passage is closest in meaning to", "Put off", ["Attract", "Feed", "Injure"], "Spines \"discourage thirsty animals from taking a bite\": they make animals less willing to try."),
         Q(2, "detail", "Why do many cacti open their pores at night?", "Cool, humid air saves water", ["Photosynthesis needs darkness", "Animals cannot reach them at night", "Their spines close during the day"], "The passage says the night air is \"cooler and more humid\", and every open pore lets water escape, so opening them then saves water. Photosynthesis still happens in the day."),
         Q(3, "reason", "How is the third paragraph related to the first two?", "It describes another way to survive drought", ["It gives evidence against the earlier claims", "It explains how cacti store carbon dioxide", "It compares deserts with wetter regions"], "The first two paragraphs describe plants that survive the dry months; the third begins \"Other desert plants avoid the dry season altogether\", a different strategy."),
         Q(3, "reason", "What can be inferred about the plants described in the last paragraph?", "They spend most dry years as seeds", ["They store more water than cacti", "They flower only once every few years", "They need shade to sprout"], "Their seeds lie in the soil for years and sprout only after heavy rain, so in dry years they exist only as seeds. Nothing is said about shade."),
       ]),
  dict(id="TOEFLR-T1-AP2", test=1, module=2, variant="lower", title="Why Leaves Change Color",
       text="In many parts of the world, the leaves of trees turn yellow, orange or red in autumn. The colors do not appear suddenly. Most of them are in the leaf all summer, but they are hidden.\n\nDuring the growing season, leaves are full of chlorophyll, the green substance that plants use to turn sunlight into food. There is so much chlorophyll that its green covers the other colors. As the days grow shorter and cooler in autumn, the tree stops making new chlorophyll. The green slowly breaks down, and the yellow and orange colors that were there all along begin to show.\n\nRed is different. Some trees, such as certain maples, make new red substances in their leaves in autumn. Bright, sunny days and cool nights help them make more, so the reds are usually strongest in autumns with that kind of weather.\n\nAfter the colors appear, the tree forms a thin layer of cells where each leaf joins its branch. This layer cuts the leaf off from the tree, and the leaf falls. The tree can then rest through the winter without losing water through its leaves.",
       qs=[
         Q(1, "detail", "According to the passage, why are yellow and orange hidden in summer?", "Green chlorophyll covers them", ["The tree has not made them yet", "Sunlight breaks them down", "They form only on cool nights"], "The passage says there is so much chlorophyll that its green covers the other colors, which were there all along."),
         Q(1, "vocab", "The word \"suddenly\" in the passage is closest in meaning to", "All at once", ["Slowly", "Brightly", "In the evening"], "\"The colors do not appear suddenly\" means they do not show up all at once."),
         Q(2, "detail", "What makes red leaves different from yellow and orange ones?", "Their color is made new in autumn", ["Their color is in the leaf all summer", "They appear only in warm autumns", "They fall before the other leaves"], "Some trees \"make new red substances in their leaves in autumn\", while yellow and orange are present all summer."),
         Q(2, "reason", "Which autumn would most likely give the brightest red leaves?", "Sunny days with cool nights", ["Cloudy days with warm nights", "Heavy rain every afternoon", "Early snow on the branches"], "The passage says bright, sunny days and cool nights help trees make more red, so that weather gives the strongest reds."),
         Q(2, "reason", "Why does the author mention the thin layer of cells?", "To explain how leaves fall", ["To show where chlorophyll is made", "To describe how red color forms", "To explain why leaves are green"], "The last paragraph says the layer cuts each leaf off so it falls, letting the tree rest without losing water."),
       ]),
  dict(id="TOEFLR-T1-AP3", test=1, module=2, variant="upper", title="Paint in a Tube",
       text="For centuries, European painters prepared their own colors in the studio. They ground pigments into powder and mixed them with oil shortly before use, because the paint dried quickly once exposed to air. Prepared paint could be stored for a short time in pieces of animal bladder tied with string, but these leaked, burst and were awkward to carry. Painting a landscape therefore usually meant sketching outdoors and finishing the picture indoors.\n\nIn 1841 the American portrait painter John Goffe Rand patented a small, squeezable metal tube with a screw cap. The tube kept paint fresh for long periods and could be closed after each use. Color manufacturers soon adopted it, and by the middle of the century a painter could buy a full range of ready-made colors and pack them in a box.\n\nThe tube did not create a new style by itself, but it removed a practical obstacle. The French Impressionists of the 1870s, who wanted to record how light and weather changed from hour to hour, could now complete entire canvases in the open air. Some of them later acknowledged that their way of working would have been difficult, if not impossible, without paint that traveled well.",
       qs=[
         Q(2, "detail", "According to the passage, what was a problem with animal bladders?", "They leaked and were hard to carry", ["They made the paint dry more slowly", "They changed the color of the paint", "They were too expensive to buy"], "The passage says bladders \"leaked, burst and were awkward to carry\"."),
         Q(2, "vocab", "The word \"obstacle\" in the passage is closest in meaning to", "Barrier", ["Benefit", "Method", "Material"], "The tube \"removed a practical obstacle\": it took away something that had stood in painters' way."),
         Q(3, "reason", "Why does the author describe how painters worked before 1841?", "To show what the tube made possible", ["To argue that older paintings were better", "To explain how pigments were invented", "To criticize the use of animal products"], "The first paragraph explains that landscapes were finished indoors; this sets up the point that the tube let painters work outdoors."),
         Q(3, "reason", "What does the passage suggest about the tube's role in Impressionism?", "It helped the style but did not cause it", ["It was the main reason the style began", "It had no effect on Impressionist painters", "It was invented by an Impressionist"], "The author says the tube \"did not create a new style by itself, but it removed a practical obstacle\", so it helped rather than caused the movement."),
         Q(3, "detail", "Which statement about the Impressionists is supported by the passage?", "They wanted to record changing light", ["They preferred to paint portraits indoors", "They ground their own pigments", "They worked mainly before 1841"], "They \"wanted to record how light and weather changed from hour to hour\"; the other options contradict the passage."),
       ]),
  dict(id="TOEFLR-T2-AP1", test=2, module=1, variant=None, title="Hunting by Sound",
       text="Most bats hunt at night, when insects are plentiful and few birds compete for them. To find prey in the dark, many species rely on echolocation. A bat produces a series of short, high-pitched calls, most of them far above the range of human hearing, and listens for the echoes that bounce back from objects around it. The time an echo takes to return tells the bat how far away an object is, and small differences between the sound reaching its left and right ears reveal the object's direction.\n\nThe calls change as a hunt progresses. While searching, a bat calls only a few times per second, which lets it scan a wide area. Once it detects an insect, it calls faster and faster, and just before the catch the calls may come close to two hundred times per second. This final burst gives the bat rapid updates on the exact position of a moving target.\n\nInsects are not defenseless. Some moths can hear bat calls and dive toward the ground when a bat approaches, and a few species even produce clicking sounds of their own that seem to interfere with the bat's ability to judge distance.",
       qs=[
         Q(1, "detail", "According to the passage, how does a bat tell how far away an object is?", "By how long an echo takes", ["By how loud its call is", "By which ear hears the call first", "By the pitch of the insect's sound"], "The passage says the time an echo takes to return tells the distance; differences between the ears give direction instead."),
         Q(2, "vocab", "The word \"plentiful\" in the passage is closest in meaning to", "Abundant", ["Small", "Hidden", "Dangerous"], "Insects are \"plentiful\" at night: there are many of them."),
         Q(2, "detail", "Why does a bat call only a few times per second while searching?", "It can scan a wide area", ["It saves its energy for flying", "Insects cannot hear slow calls", "Its ears need time to rest"], "The passage says the slow rate \"lets it scan a wide area\"."),
         Q(3, "reason", "What is the purpose of the last paragraph?", "To show prey can escape bats", ["To explain why bats hunt at night", "To describe how bats learn to call", "To compare bats with birds"], "It begins \"Insects are not defenseless\" and describes moths that dive or click to escape bats."),
         Q(3, "reason", "What can be inferred about the clicking moths?", "Bats may misjudge where they are", ["They hunt bats in return", "They cannot hear the calls of bats", "They fly only in daylight"], "Their clicks \"seem to interfere with the bat's ability to judge distance\", so a bat may misjudge where they are."),
       ]),
  dict(id="TOEFLR-T2-AP2", test=2, module=2, variant="lower", title="Supply and Demand",
       text="Why does the price of strawberries change during the year? Economists answer this kind of question with two ideas: supply and demand.\n\nSupply is the amount of a product that sellers are ready to sell. Demand is the amount that buyers want to buy. When a product is scarce but many people want it, buyers compete with one another, and the price goes up. When there is more of a product than people want, sellers lower the price to attract buyers.\n\nStrawberries are a good example. In early summer, farms near a city harvest large amounts of fruit at the same time. The supply is high, so shops lower their prices to sell the berries before they spoil. In winter, the fruit must come from far away, which costs more, and there is less of it in the shops. Even if people want strawberries just as much as in summer, the lower supply pushes the price up.\n\nPrices also send signals. A high price tells farmers that buyers will pay well for a product, so some farmers decide to grow more of it the next year.",
       qs=[
         Q(1, "detail", "According to the passage, what is demand?", "The amount buyers want to buy", ["The amount sellers can sell", "The price set by farmers", "The cost of moving goods"], "The passage defines demand as \"the amount that buyers want to buy\"; the amount sellers are ready to sell is supply."),
         Q(1, "vocab", "The word \"scarce\" in the passage is closest in meaning to", "In short supply", ["Very popular", "Low in price", "Easy to find"], "A product that is scarce is one there is little of, which is why buyers compete for it."),
         Q(2, "detail", "Why are strawberries cheaper in early summer?", "Nearby farms harvest a lot at once", ["People want fewer strawberries then", "Shops pay farmers less in summer", "Winter fruit is still in the shops"], "Farms near the city harvest large amounts at the same time, so supply is high and shops lower prices."),
         Q(2, "reason", "Why does the author discuss strawberries?", "To give an example of the two ideas", ["To argue that fruit is too expensive", "To compare summer and winter weather", "To explain how berries are grown"], "The author says \"Strawberries are a good example\" of how supply and demand change prices."),
         Q(2, "reason", "What would the author most likely expect after a year of high potato prices?", "Farmers plant more potatoes", ["Farmers stop growing potatoes", "Buyers want more potatoes", "Shops stop selling potatoes"], "The last paragraph says a high price signals that buyers pay well, so some farmers grow more of that crop the next year."),
       ]),
  dict(id="TOEFLR-T2-AP3", test=2, module=2, variant="upper", title="The Dust Bowl",
       text="During the 1930s, the southern Great Plains of the United States suffered a disaster that came to be known as the Dust Bowl. Its causes were partly natural and partly human. In the preceding decades, rising wheat prices and new tractors had encouraged farmers to plow millions of acres of native grassland. The deep roots of those grasses had anchored the light soil through earlier dry periods; plowed fields, by contrast, were often left bare between harvests.\n\nWhen a severe drought began in the early 1930s, crops failed and the exposed soil dried to powder. Strong winds then lifted it into enormous clouds, some of which carried dust as far as the Atlantic coast. Many families, unable to farm or repay their debts, abandoned their land and moved west in search of work.\n\nThe crisis also changed how the federal government approached farming. In 1935 Congress created the Soil Conservation Service, which promoted methods such as planting rows of trees to break the wind, plowing along the natural curves of the land, and returning damaged fields to grass. These practices were intended not merely to repair the damage but to prevent a repetition.",
       qs=[
         Q(2, "detail", "According to the passage, what had protected the soil in earlier dry periods?", "The roots of native grasses", ["Rows of trees planted by farmers", "Plowing along the curves of the land", "Higher rainfall in the region"], "The deep roots of native grasses \"had anchored the light soil through earlier dry periods\"; trees and curved plowing came later."),
         Q(2, "vocab", "The word \"anchored\" in the passage is closest in meaning to", "Held in place", ["Dried out", "Covered up", "Made richer"], "Roots \"anchored the light soil\": they held it so the wind could not move it."),
         Q(3, "reason", "Why does the author mention rising wheat prices and new tractors?", "To explain why so much grassland was plowed", ["To show that farming was easy in the 1930s", "To argue that the drought was caused by people", "To describe where the families moved"], "They \"encouraged farmers to plow millions of acres of native grassland\", which left the soil exposed."),
         Q(3, "reason", "What does the passage suggest about the causes of the Dust Bowl?", "Drought did more harm on plowed land", ["The drought alone caused the dust storms", "Wind patterns changed in the 1930s", "Farmers had never faced dry years"], "The author says the causes were \"partly natural and partly human\": the drought hit fields left bare by plowing, while grass-covered soil had survived earlier dry periods."),
         Q(3, "detail", "Which practice did the Soil Conservation Service promote?", "Returning damaged fields to grass", ["Plowing more land to grow wheat", "Leaving fields bare between harvests", "Moving farms to the Atlantic coast"], "The service promoted tree rows, plowing along curves and \"returning damaged fields to grass\"."),
       ]),
  dict(id="TOEFLR-D-AP1", test=0, module=1, variant=None, title="Tides",
       text="Along most coastlines, the level of the sea rises and falls about twice a day. These changes, called tides, are caused mainly by the gravity of the Moon. The Moon pulls most strongly on the side of the Earth that faces it, so the ocean there bulges slightly toward the Moon. A second bulge forms on the opposite side of the planet, where the Moon's pull is weakest. As the Earth turns, a given coast passes through both bulges, which is why it usually has two high tides and two low tides each day.\n\nThe Sun affects tides too, though its effect is less than half as strong because it is so much farther away. When the Sun and the Moon line up, at new moon and full moon, their pulls combine, and the difference between high and low water is largest. These are called spring tides, although they have nothing to do with the season. When the Sun and Moon pull at right angles, the tidal range is smallest; these are neap tides.\n\nThe shape of a coast can greatly increase the range. In some narrow bays, the water rises many meters between low and high tide.",
       qs=[
         Q(1, "detail", "According to the passage, what mainly causes tides?", "The gravity of the Moon", ["The heat of the Sun", "Wind over the ocean", "The shape of the coast"], "The passage says tides \"are caused mainly by the gravity of the Moon\"; the Sun's effect is less than half as strong."),
         Q(2, "detail", "When do spring tides occur?", "When the Sun and Moon line up", ["Only in the spring season", "When the Moon is farthest away", "When the Sun and Moon are at right angles"], "Spring tides happen at new and full moon, when the Sun and Moon line up; right angles give neap tides."),
         Q(2, "vocab", "The word \"bulges\" in the passage is closest in meaning to", "Swells outward", ["Freezes", "Becomes calm", "Flows away"], "The ocean \"bulges slightly toward the Moon\": it swells out in that direction."),
         Q(3, "reason", "Why does the author say spring tides \"have nothing to do with the season\"?", "To prevent a likely misunderstanding", ["To show that tides are hard to predict", "To introduce the topic of neap tides", "To explain why tides are strongest in spring"], "The name suggests the season, so the author clarifies that it refers to the Sun and Moon lining up, not to spring."),
         Q(3, "reason", "What can be inferred about a coast in a narrow bay?", "Its tides may rise very high", ["It has only one high tide a day", "It is not affected by the Moon", "It has no neap tides"], "The last paragraph says the shape of a coast can greatly increase the range, and in some narrow bays the water rises many meters."),
       ]),
  dict(id="TOEFLR-D-AP2", test=0, module=1, variant=None, title="The Power of Defaults",
       text="When people face a choice, they often stick with whatever option is already selected for them. Economists and psychologists call this preselected option the default, and research suggests that defaults can strongly shape behavior even when changing them takes only a moment.\n\nRetirement savings offer a well-known example. At some companies, new employees must actively sign up to join the savings plan; at others, they are enrolled automatically and must fill out a form if they wish to leave. Studies of such companies have found that participation is far higher when joining is the default, although the plan, the benefits and the effort needed to switch are almost identical.\n\nResearchers suggest several reasons. Making a decision requires attention, and people may postpone a choice that seems complicated. Some people also interpret the default as a recommendation, assuming that whoever set it had good reasons. Finally, people tend to feel a loss more sharply than an equal gain, so giving up the current option can feel like a loss.\n\nBecause defaults are so influential, those who design forms and programs carry a responsibility to choose them with care.",
       qs=[
         Q(1, "vocab", "The word \"postpone\" in the passage is closest in meaning to", "Delay", ["Complete", "Explain", "Refuse"], "People \"may postpone a choice that seems complicated\": they put it off until later."),
         Q(2, "detail", "According to the passage, what differed between the two kinds of companies?", "Which option was preselected", ["The benefits of the plan", "The effort needed to switch", "The type of savings plan"], "The plan, benefits and effort were \"almost identical\"; only whether joining was the default differed."),
         Q(2, "detail", "Which is NOT given as a reason defaults are powerful?", "Defaults are usually cheaper", ["Decisions require attention", "Defaults can seem like advice", "Losses feel stronger than gains"], "The passage gives attention, the default as a recommendation, and losses felt more sharply; cost is never mentioned."),
         Q(3, "reason", "Why does the author describe retirement savings plans?", "To illustrate the effect of a default", ["To recommend a type of savings plan", "To explain how companies choose plans", "To show that employees dislike forms"], "The author calls it \"a well-known example\" of how defaults shape behavior."),
         Q(3, "reason", "Which statement best expresses the author's conclusion?", "Defaults need careful choosing", ["Defaults should be avoided entirely", "People should ignore recommendations", "Forms should offer fewer options"], "The last sentence says those who design forms \"carry a responsibility to choose them with care\"."),
       ]),
  dict(id="TOEFLR-D-AP3", test=0, module=1, variant=None, title="The Beginnings of Jazz",
       text="Jazz developed in the late nineteenth and early twentieth centuries, and the city of New Orleans played a central part in its birth. As a busy port, the city brought together people of African, European and Caribbean backgrounds, along with their musical traditions. Brass bands marched in parades and at funerals, dance halls hired small groups to play late into the night, and church choirs, work songs and the blues all contributed sounds and rhythms.\n\nEarly jazz musicians borrowed from all of these sources, but they also changed how the music was played. Instead of following a written score note for note, players often improvised, creating new melodies on the spot. In a typical early jazz band, the cornet or trumpet carried the main tune while the clarinet and trombone wove lines around it, so that several melodies sounded at once.\n\nThe new music did not stay in one city. Beginning around the time of the First World War, many musicians moved north to cities such as Chicago and New York, and records and radio carried their playing to listeners who had never heard a live jazz band.",
       qs=[
         Q(1, "detail", "According to the passage, why did New Orleans matter to early jazz?", "It mixed many musical traditions", ["It had the first recording studios", "It banned written music", "It was home to the first radio stations"], "As a busy port, the city brought together people of different backgrounds \"along with their musical traditions\"."),
         Q(2, "vocab", "The word \"improvised\" in the passage is closest in meaning to", "Made up as they played", ["Practiced for a long time", "Copied from records", "Played very loudly"], "The passage explains it at once: \"creating new melodies on the spot\"."),
         Q(2, "detail", "In a typical early jazz band, which instrument carried the main tune?", "The cornet or trumpet", ["The clarinet", "The trombone", "The drums"], "The cornet or trumpet carried the main tune while the clarinet and trombone wove lines around it."),
         Q(2, "reason", "What is the main idea of the second paragraph?", "Jazz changed how music was played", ["Brass bands played at funerals", "Jazz spread to Chicago and New York", "Church choirs sang the blues"], "It says early players \"also changed how the music was played\" by improvising and playing several melodies at once."),
         Q(3, "reason", "What can be inferred about records and radio?", "They helped jazz reach new audiences", ["They replaced live jazz completely", "They began in New Orleans", "They made improvising impossible"], "They carried the playing \"to listeners who had never heard a live jazz band\", spreading the music."),
       ]),
  dict(id="TOEFLR-D-AP4", test=0, module=1, variant=None, title="How Vaccines Work",
       text="The human immune system learns from experience. When a germ enters the body for the first time, the immune system needs several days to recognize it and produce antibodies, proteins that attach to the germ and help destroy it. During that time the person may become seriously ill. Afterward, however, some immune cells remain in the body as memory cells. If the same germ returns, these cells respond within hours, often before any symptoms appear.\n\nVaccines take advantage of this memory. A vaccine exposes the immune system to a harmless version or a single part of a germ, such as a surface protein. Because this material cannot cause the disease, the person does not become sick, yet the immune system still learns to recognize the germ and forms memory cells.\n\nSome vaccines provide protection for life, while others need booster doses because memory fades or because the germ changes over time. When enough people in a community are immune, a germ has trouble spreading from person to person. This also protects people who cannot be vaccinated, such as newborn babies.",
       qs=[
         Q(1, "detail", "According to the passage, what are antibodies?", "Proteins that help destroy germs", ["Harmless versions of germs", "Cells that cause symptoms", "Doses given to newborn babies"], "The passage defines antibodies as \"proteins that attach to the germ and help destroy it\"."),
         Q(2, "detail", "Why does a vaccinated person usually not become sick from the vaccine?", "It cannot cause the disease", ["The vaccine contains antibodies", "Memory cells destroy the vaccine", "The dose is given over several days"], "A vaccine uses a harmless version or a single part of a germ, which \"cannot cause the disease\"."),
         Q(2, "vocab", "The word \"fades\" in the passage is closest in meaning to", "Weakens", ["Grows", "Spreads", "Returns"], "Booster doses are needed because memory \"fades\", becoming weaker over time."),
         Q(3, "reason", "How does the second paragraph relate to the first?", "It applies the idea of immune memory", ["It disagrees with the first paragraph", "It describes a different body system", "It lists the symptoms of disease"], "The first paragraph explains memory cells, and the second begins \"Vaccines take advantage of this memory\"."),
         Q(3, "reason", "What can be inferred about newborn babies?", "They depend on others being immune", ["They need booster doses at birth", "They already have memory cells", "They cannot catch any germs"], "Babies who cannot be vaccinated are protected when enough people around them are immune, because the germ has trouble spreading."),
       ]),
]
